/* global test expect */
import { DateTime, Duration, Interval, Settings, FixedOffsetZone } from "../../src/luxon";
import Helpers from "../helpers";

const withThrowOnInvalid = Helpers.setUnset("throwOnInvalid");

// #1
test("Interval.fromISO works with Settings.throwOnInvalid", () => {
  withThrowOnInvalid(true, () => {
    expect(Interval.fromISO("2007-03-01T13:00:00/P1Y2M10DT2H30M").isValid).toBe(true);
    expect(Interval.fromISO("P1Y2M10DT2H30M/2008-05-11T15:30:00").isValid).toBe(true);
    expect(Interval.fromISO("2007-03-01T13:00:00/2008-05-11T15:30:00").isValid).toBe(true);
    expect(() => Interval.fromISO("blah")).toThrow();
    expect(() => Interval.fromISO("2007-03-01T13:00:00/blah")).toThrow();
    expect(() => Interval.fromISO("blah/2008-05-11T15:30:00")).toThrow();
  });
});

// #2
test("DateTime#plus works across the 100 barrier when passing through February", () => {
  const d = DateTime.fromISO("0099-12-31").plus({ day: 61 });
  expect(d.year).toBe(100);
  expect(d.month).toBe(3);
  expect(d.day).toBe(2);

  const d2 = DateTime.fromISO("0099-12-31").plus({ day: 60 });
  expect([d2.year, d2.month, d2.day]).toEqual([100, 3, 1]);

  const d3 = DateTime.fromISO("0099-12-31").plus({ day: 59 });
  expect([d3.year, d3.month, d3.day]).toEqual([100, 2, 28]);

  // and the reverse
  const d4 = DateTime.fromISO("0100-03-02").minus({ day: 61 });
  expect([d4.year, d4.month, d4.day]).toEqual([99, 12, 31]);
});

// #3
test("DateTime#isInDST() returns true for 1974 whole year in USA - from January 6th to October 27th", () => {
  const zoned = DateTime.fromMillis(391147200000).setZone("America/Los_Angeles");
  expect(zoned.set({ year: 1974, month: 1, day: 6, hour: 12 }).isInDST).toBe(true);
  expect(zoned.set({ year: 1974, month: 10, day: 27, hour: 1 }).isInDST).toBe(true);
  expect(zoned.set({ year: 1974, month: 1, day: 5, hour: 12 }).isInDST).toBe(false);
  expect(zoned.set({ year: 1974, month: 10, day: 28, hour: 12 }).isInDST).toBe(false);
  // regular years still work
  expect(zoned.set({ month: 1 }).isInDST).toBe(false);
  expect(zoned.set({ month: 5 }).isInDST).toBe(true);
  expect(zoned.set({ month: 12 }).isInDST).toBe(false);
});

// #4
test("Duration#normalize can convert all unit pairs", () => {
  const units = ["years", "quarters", "months", "weeks", "days", "hours", "minutes", "seconds", "milliseconds"];
  for (const acc of ["casual", "longterm"]) {
    for (const a of units) {
      for (const b of units) {
        const d = Duration.fromObject({ [a]: 1, [b]: 1 }, { conversionAccuracy: acc }).normalize();
        expect(d.isValid).toBe(true);
        for (const v of Object.values(d.toObject())) {
          expect(isFinite(v)).toBe(true);
        }
        const shifted = Duration.fromObject({ [a]: 1 }, { conversionAccuracy: acc }).shiftTo(b);
        expect(isFinite(shifted.get(b))).toBe(true);
      }
    }
  }
});

// #5
test("DateTime#toISODate() correctly pads negative years", () => {
  expect(DateTime.fromObject({ year: -100, month: 5, day: 25 }, { zone: "utc" }).toISODate()).toBe("-0100-05-25");
  expect(DateTime.fromObject({ year: -5, month: 5, day: 25 }, { zone: "utc" }).toISODate()).toBe("-0005-05-25");
  expect(DateTime.fromObject({ year: -118040, month: 5, day: 25 }, { zone: "utc" }).toISODate()).toBe("-118040-05-25");
});

// #6
test("FixedOffsetZone is invalid when constructed with a non-numeric offset", () => {
