  expect(new FixedOffsetZone(60).isValid).toBe(true);
});

test("A DateTime in an invalid FixedOffsetZone is itself invalid", () => {
  expect(DateTime.local().setZone(new FixedOffsetZone("blah")).isValid).toBe(false);
});
